342	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
343	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
344		for id, c := range s.campaigns {
345			if id == excludeCampaign || c.Ended {
346				continue
347			}
348			if _, ok := c.index[deviceID]; ok {
349				return true
350			}
351		}
352		return false
353	}
354	
355	// operationID 是修复前的旧标识方案：冒号拼接。活动或设备标识含冒号时，
356	// 不同（活动, 设备）组合会拼出相同标识，仅用于兼容校验修复前保存的活动；
357	// 新活动一律使用 encodeOperationIDV2。
358	func operationID(campaignID, deviceID, stage string) string {
359		return campaignID + ":" + deviceID + ":" + stage
360	}
361	
362	// 操作标识方案编号，随活动一起持久化；缺省（旧存储）为旧方案。
363	const (
364		opIDSchemeLegacy = 0
365		opIDSchemeV2     = 1
366	)
367	
368	const opIDV2Prefix = "v2:"
369	
370	// encodeOperationIDV2 生成无歧义的操作标识：活动与设备标识用长度前缀编码，
371	// 任何非空标识（含冒号、中文等）都按原字符串精确保留，（活动, 设备, 阶段）
372	// 三元组与标识一一对应。nonce 用于避开与存储内已有标识（如旧方案标识）
373	// 偶然相同的情形。
374	func encodeOperationIDV2(nonce int, campaignID, deviceID, stage string) string {
375		return fmt.Sprintf("v2:%d:%d:%s%d:%s%s",
376			nonce, len(campaignID), campaignID, len(deviceID), deviceID, stage)
377	}
378	
379	// parseOperationIDV2 解析 v2 操作标识，还原活动、设备与阶段。
380	// 只接受规范编码（解析后原样重编码必须等于入参）。
381	func parseOperationIDV2(id string) (campaignID, deviceID, stage string, ok bool) {
382		rest, found := strings.CutPrefix(id, opIDV2Prefix)
383		if !found {
384			return "", "", "", false
385		}
386		readInt := func() (int, bool) {
387			i := strings.IndexByte(rest, ':')
388			if i <= 0 {
389				return 0, false
390			}
391			n, err := strconv.Atoi(rest[:i])
392			if err != nil || n < 0 {
393				return 0, false
394			}
395			rest = rest[i+1:]
396			return n, true
397		}
398		readStr := func(n int) (string, bool) {
399			if n <= 0 || len(rest) < n {
400				return "", false
401			}
402			s := rest[:n]
403			rest = rest[n:]
404			return s, true
405		}
406		nonce, ok1 := readInt()
407		lenC, ok2 := readInt()
408		if !ok1 || !ok2 {
409			return "", "", "", false
410		}
411		campaignID, ok1 = readStr(lenC)
412		lenD, ok2 := readInt()
413		if !ok1 || !ok2 {
414			return "", "", "", false
415		}
416		deviceID, ok1 = readStr(lenD)
417		if !ok1 {
418			return "", "", "", false
419		}
420		stage = rest
421		if !validStage(stage) || encodeOperationIDV2(nonce, campaignID, deviceID, stage) != id {
422			return "", "", "", false
423		}
424		return campaignID, deviceID, stage, true
425	}
426	
427	func validStage(stage string) bool {
428		return stage == StageDownload || stage == StageInstall || stage == StageRollback
429	}
430	
431	// validV2OpID 校验标识是否是指定（活动, 设备, 阶段）的规范 v2 操作标识。
432	func validV2OpID(opID, campaignID, deviceID, stage string) bool {
433		cid, did, st, ok := parseOperationIDV2(opID)
434		return ok && cid == campaignID && did == deviceID && st == stage
435	}
436	
437	// takenOperationIDs 收集存储内全部活动（含已结束）正在使用或结果历史中
438	// 出现过的操作标识，供新活动生成标识时避开相同值。
439	func (s *Store) takenOperationIDs() map[string]bool {
440		taken := map[string]bool{}
441		for _, c := range s.campaigns {
442			for _, cd := range c.Devices {
443				taken[cd.Download.ID] = true
444				taken[cd.Install.ID] = true
445				if cd.Rollback.ID != "" {
446					taken[cd.Rollback.ID] = true
447				}
448			}
449			for _, r := range c.Results {
450				taken[r.OperationID] = true
451			}
452		}
453		return taken
454	}
455	
456	func containsString(list []string, v string) bool {
457		for _, x := range list {
458			if x == v {
459				return true
460			}
461		}
462		return false
463	}
464	
465	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
466	//
467	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
468	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
469	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
470	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
471	// 后续普通上报不改变它。
472	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
473	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
474	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
475	// 且可在窗口外、截止前提交结果。
476	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
477	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
478	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
479	// 活动已结束（无论因超时还是提前成功/失败结束、无论领取时间在原截止前、
480	// 恰好截止或截止后）时领取是纯拒绝：返回 ErrCampaignEnded，不推进时间基线、
481	// 不改活动结论、结束时间、设备状态与状态时间、结果历史和设备影子，也不落盘，
482	// 因此被拒绝的领取时间不会影响后续合法请求或重开存储后的倒退判断。
483	// 活动仍在执行而领取首次到达截止时间时保留原有截止处理：不派发操作，
484	// 全部未结束设备按阶段记为超时（等待或正在回滚的记回滚超时），已有终态
485	// 保持不变，以本次领取时间结束活动；此次结束时间仍参与后续倒退判断。
486	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
487		s.mu.Lock()
488		defer s.mu.Unlock()
489		if err := s.checkOpen(); err != nil {
490			return nil, err
491		}
492		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
493		if err != nil {
494			return nil, err
495		}
496		if at.IsZero() {
497			return nil, ErrInvalidTime
498		}
499		if at.Before(c.LastTime) {
500			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
501		}
502		if c.Ended {
503			// 已结束活动的领取是纯拒绝：不推进时间基线、不改状态、不落盘，
504			// 否则被拒绝的领取时间会把基线推过真正已接受的时间，
505			// 使随后本来合法的请求被误判为时间倒退。
506			return nil, ErrCampaignEnded
507		}
508		var op *Operation
509		var reject error
510		err = s.commit(func() error {
511			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
512			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
513			if !at.Before(c.Deadline) {
514				c.LastTime = at
515				s.applyTimeout(c, at)
516				reject = ErrCampaignEnded
517				return nil
518			}
519			if isTerminal(cd.Status) {
520				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
521				return nil
522			}
523			c.LastTime = at
524			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
525			if out := outstandingOp(c, cd); out != nil {
526				op = out
527				return nil
528			}
529			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
530			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
531			if cd.Status == DeviceAwaitingRollback {
532				if !s.devices[deviceID].Online {
533					return nil
534				}
535				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
536					return nil
537				}
538				cd.Rollback.Claimed = true
539				cd.Rollback.ClaimedAt = at
540				cd.Status = DeviceRollingBack
541				cd.Phase = StageRollback
542				cd.At = at
543				op = &Operation{
544					ID:            cd.Rollback.ID,
545					CampaignID:    c.ID,
546					DeviceID:      deviceID,
547					Kind:          StageRollback,
548					TargetVersion: cd.RollbackTarget,
549				}
550				return nil
551			}
552			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
553			if !s.batchOpen(c, cd) {
554				return nil
555			}
556			if !s.devices[deviceID].Online {
557				return nil // 离线保留待办，上线后继续
558			}
559			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
560				return nil // 窗口外不派发新操作；窗口为 [start, end)
561			}
562			if !cd.Download.Claimed {
563				// 首次领取下载前再次检查当前版本。
564				current := s.devices[deviceID].Version
565				if !containsString(s.versions[c.Target].AllowedFrom, current) {
566					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
567					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
568					cd.Download.Claimed = true
569					cd.Download.ClaimedAt = at
570					cd.Download.HasResult = true
571					cd.Download.Success = false
572					cd.Download.Reason = reason
573					cd.Download.At = at
574					s.failDevice(c, cd, StageDownload, reason, at)
575					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
576					return nil
577				}
578				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
579				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
580				if c.RollbackOnFailure && cd.RollbackTarget == "" {
581					cd.RollbackTarget = current
582				}
583				cd.Download.Claimed = true
584				cd.Download.ClaimedAt = at
585				cd.Status = DeviceDownloading
586				cd.At = at
587				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
588				return nil
589			}
590			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
591			cd.Install.Claimed = true
592			cd.Install.ClaimedAt = at
593			cd.Status = DeviceInstalling
594			cd.At = at
595			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
596			return nil
597		})
598		if err != nil {
599			return nil, err
600		}
601		if reject != nil {
602			return nil, reject
603		}
604		return op, nil
605	}
606	
607	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
608	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
609		switch {
610		case cd.Download.Claimed && !cd.Download.HasResult:
611			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
612		case cd.Install.Claimed && !cd.Install.HasResult:
613			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
614		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
615			// 已领取但未完成的回滚再次领取仍返回同一标识，并继续告知恢复目标版本。
616			return &Operation{
617				ID:            cd.Rollback.ID,
618				CampaignID:    c.ID,
619				DeviceID:      cd.DeviceID,
620				Kind:          StageRollback,
621				TargetVersion: cd.RollbackTarget,
622			}
623		default:
624			return nil
625		}
626	}
627	
628	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
629	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
630		for _, other := range c.Devices {
631			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
632				return false
633			}
634		}
635		return true
636	}
637	
638	// SubmitResult 接收设备提交的操作结果。
639	//
640	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
641	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
642	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
643	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
644	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
645	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
646	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
647	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
648	// 已领取且尚未接受结果的操作在截止时刻及以后提交时，结果已经迟到，
649	// 不校验附带上报与失败原因、不接收为操作结果：若提交前活动仍在执行，
650	// 本次作为首次触发截止处理——未结束设备全部超时（等待或正在回滚的记回滚
651	// 超时），活动以本次提交时间失败结束，返回 ErrCampaignEnded，本次确实推进
652	// 的时间仍参与后续倒退判断；若活动此前已因超时结束，则只返回 ErrCampaignEnded，
653	// 是不推进时间基线、不改结束时间与设备状态的纯拒绝，因此随后不早于结束时间的
654	// 合法时间不会因这次拒绝而被判为倒退。
655	// 普通设备上报不经过本方法，也不会推进活动。
656	func (s *Store) SubmitResult(res OperationResult) error {
657		s.mu.Lock()
658		defer s.mu.Unlock()
659		if err := s.checkOpen(); err != nil {
660			return err
661		}
662		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
663		if err != nil {
664			return err
665		}
666		if res.At.IsZero() {
667			return ErrInvalidTime
668		}
669		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
670		var stage string
671		var op *opState
672		switch res.OperationID {
673		case cd.Download.ID:
674			stage, op = StageDownload, &cd.Download
675		case cd.Install.ID:
676			stage, op = StageInstall, &cd.Install
677		case cd.Rollback.ID:
678			stage, op = StageRollback, &cd.Rollback
679		default:
680			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
681		}
682		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
683		// 不推进时间基线；不同结果冲突。均不改变状态。
684		if op.HasResult {
685			if resultMatches(op, res) {
686				return nil
687			}
688			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
689		}
690		if res.At.Before(c.LastTime) {
691			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
692		}
693		if !op.Claimed {
694			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
695			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
696		}
697		// 已领取且尚未接受结果的操作在截止时刻及以后提交：结果已经迟到，
698		// 不再接收为操作结果，也不校验附带上报或失败原因。
699		if !res.At.Before(c.Deadline) {
700			if c.Ended {
701				// 活动此前已因超时结束（显式推进或更早的迟到提交触发）：
702				// 本次拒绝是纯拒绝，不推进时间基线、不改结束时间、不改设备状态，
703				// 否则随后原本合法的时间会因这次拒绝而被判为倒退。
704				return ErrCampaignEnded
705			}
706			// 活动仍在执行，本次是首次触发截止处理：未结束设备全部超时
707			// （等待/正在回滚的记回滚超时），活动以失败结束，状态时间与活动
708			// 结束时间采用本次提交时间；这次确实推进的时间仍参与后续倒退判断。
709			if err := s.commit(func() error {
710				c.LastTime = res.At
711				s.applyTimeout(c, res.At)
712				return nil
713			}); err != nil {
714				return err
715			}
716			return ErrCampaignEnded
717		}
718		if !res.Success && res.Reason == "" {
719			return ErrInvalidReason
720		}
721		// 安装/回滚成功附带的设备上报与普通 Report 共用 checkReport 的同一套
722		// 规则（必填字段、版本约束、序号过旧/重复/冲突）；这里先校验并记下判定，
723		// 实际写入在下面的同一次 commit 内与活动、历史一起完成。附带上报任何
724		// 不合规都映射为 ErrInvalidReport，不改成普通上报的错误类别。
725		var repIn reportInput
726		var repCfg json.RawMessage
727		var repVerdict reportVerdict
728		if res.Success && (stage == StageInstall || stage == StageRollback) {
729			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
730			wantVersion := c.Target
731			if stage == StageRollback {
732				wantVersion = cd.RollbackTarget
733			}
734			repIn = reportInput{
735				DeviceID: res.DeviceID,
736				Seq:      res.Seq,
737				At:       res.At,
738				Version:  res.Version,
739				Config:   res.Config,
740			}
741			var checkErr error
742			repCfg, repVerdict, checkErr = checkReport(s.devices[res.DeviceID], repIn, wantVersion)
743			if checkErr != nil {
744				return reportAttachedError(checkErr.(errBadReport))
745			}
746		}
747		var reject error
748		err = s.commit(func() error {
749			// 到达这里时提交时间早于截止（截止时刻及以后已在提交前处理）。
750			// 一致状态下持有已领取未完成操作的设备尚未终态、活动也不会结束，
751			// 此判断仅作为防御性兜底：活动结束后的新结果拒绝且不改状态。
752			if c.Ended {
753				reject = ErrCampaignEnded
754				return nil
755			}
756			if isTerminal(cd.Status) {
757				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
758				return nil
759			}
760			c.LastTime = res.At
761			op.HasResult = true
762			op.Success = res.Success
763			op.Reason = res.Reason
764			op.At = res.At
765			if !res.Success {
766				switch {
767				case stage == StageInstall && c.RollbackOnFailure:
768					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
769					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
770					s.enterRollback(c, cd, res.Reason, res.At)
771				case stage == StageRollback:
772					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
773					s.finishRollbackFailure(c, cd, res.Reason, res.At)
774				default:
775					s.failDevice(c, cd, stage, res.Reason, res.At)
776				}
777				return nil
778			}
779			switch stage {
780			case StageDownload:
781				cd.Status = DeviceReady
782				cd.Phase = StageInstall
783				cd.Reason = ""
784				cd.At = res.At
785			case StageInstall:
786				// 安装成功：附带上报与活动同时更新、一起持久化。
787				// 同序号的完全重复上报不重新写入影子（不刷新在线状态与差异时间）。
788				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
789				op.ResultSeq = res.Seq
790				op.ResultVersion = res.Version
791				op.ResultConfig = cloneRaw(res.Config)
792				cd.Status = DeviceSucceeded
793				cd.Phase = StageInstall
794				cd.Reason = ""
795				cd.At = res.At
796			case StageRollback:
797				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
798				// 期望配置、修订号与审计保持不变；重复上报不重新写入影子。
799				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
800				op.ResultSeq = res.Seq
801				op.ResultVersion = res.Version
802				op.ResultConfig = cloneRaw(res.Config)
803				cd.Status = DeviceRollbackSucceeded
804				cd.Phase = StageRollback
805				cd.Reason = ""
806				cd.At = res.At
807			}
808			c.Results = append(c.Results, ResultRecord{
809				DeviceID:    cd.DeviceID,
810				OperationID: op.ID,
811				Stage:       stage,
812				Success:     true,
813				Version:     op.ResultVersion,
814				At:          res.At,
815			})
816			s.settle(c, res.At)
817			return nil
818		})
819		if err != nil {
820			return err
821		}
822		return reject
823	}
824	
825	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
826	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
827	// 使活动结束后的重复提交仍然有效。
828	func resultMatches(op *opState, res OperationResult) bool {
829		if op.Success != res.Success || op.Reason != res.Reason {
830			return false
831		}
832		if op.Success && op.ResultSeq != 0 {
833			return op.ResultSeq == res.Seq &&
834				op.ResultVersion == res.Version &&
835				rawEqual(op.ResultConfig, res.Config)
836		}
837		return true
838	}
839	
840	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
841	// 保留原安装失败的原因与时间，令设备等待回滚（非终态）；
842	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
843	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
844		cd.Status = DeviceAwaitingRollback
845		cd.Phase = StageRollback
846		cd.Reason = reason
847		cd.At = at
848		c.Results = append(c.Results, ResultRecord{
849			DeviceID:    cd.DeviceID,
850			OperationID: cd.Install.ID,
851			Stage:       StageInstall,
852			Success:     false,
853			Reason:      reason,
854			At:          at,
855		})
856		skipLaterBatches(c, cd, at)
857		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
858	}
859	
860	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
861	// 设备以回滚失败结束，影子不变（失败结果不附带、不应用上报）。
862	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
863		cd.Status = DeviceRollbackFailed
864		cd.Phase = StageRollback
865		cd.Reason = reason
866		cd.At = at
867		c.Results = append(c.Results, ResultRecord{
868			DeviceID:    cd.DeviceID,
869			OperationID: cd.Rollback.ID,
870			Stage:       StageRollback,
871			Success:     false,
872			Reason:      reason,
873			At:          at,
874		})
875		s.settle(c, at)
876	}
877	
878	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
879	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
880		for _, other := range c.Devices {
881			if other.Batch > cd.Batch && !isTerminal(other.Status) {
882				other.Status = DeviceSkipped
883				other.Phase = pendingPhase(other)
884				other.Reason = "not executed: previous batch failed"
885				other.At = at
886			}
887		}
888	}
889	
890	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
891	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
892	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
893		cd.Status = DeviceFailed
894		cd.Phase = phase
895		cd.Reason = reason
896		cd.At = at
897		c.Results = append(c.Results, ResultRecord{
898			DeviceID:    cd.DeviceID,
899			OperationID: opIDFor(cd, phase),
900			Stage:       phase,
901			Success:     false,
902			Reason:      reason,
903			At:          at,
904		})
905		skipLaterBatches(c, cd, at)
906		s.settle(c, at)
907	}
908	
909	func opIDFor(cd *campaignDevice, phase string) string {
910		switch phase {
911		case StageInstall:
912			return cd.Install.ID
913		case StageRollback:
914			return cd.Rollback.ID
915		default:
916			return cd.Download.ID
917		}
918	}
919	
920	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
921	func pendingPhase(cd *campaignDevice) string {
922		if cd.Download.HasResult && cd.Download.Success {
923			return StageInstall
924		}
925		return StageDownload
926	}
927	
928	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
929	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
930	// 以回滚阶段超时结束；不改写或清空影子。
931	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
932		if c.Ended {
933			return
934		}
935		for _, cd := range c.Devices {
936			if isTerminal(cd.Status) {
937				continue
938			}
939			switch cd.Status {
940			case DeviceAwaitingRollback, DeviceRollingBack:
941				cd.Status = DeviceRollbackTimeout
942				cd.Phase = StageRollback
943			default:
944				cd.Status = DeviceTimeout
945				cd.Phase = pendingPhase(cd)
946			}
947			cd.Reason = "deadline exceeded"
948			cd.At = at
949		}
950		c.Status = CampaignFailed
951		c.Ended = true
952		c.EndedAt = at
953	}
954	
955	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
956	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
957	func (s *Store) settle(c *campaignState, at time.Time) {
958		allSucceeded := true
959		for _, cd := range c.Devices {
960			if !isTerminal(cd.Status) {
961				return
962			}
963			if cd.Status != DeviceSucceeded {
964				allSucceeded = false
965			}
966		}
967		c.Ended = true
968		c.EndedAt = at
969		if allSucceeded {
970			c.Status = CampaignSucceeded
971		} else {
972			c.Status = CampaignFailed
973		}
974	}
975	
976	func isTerminal(status string) bool {
977		switch status {
978		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
979			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
980			return true
981		default:
982			return false
983		}
984	}
985	
986	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
987	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
988	// 未到截止时间或活动已结束时为空操作。
989	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
990		s.mu.Lock()
991		defer s.mu.Unlock()
992		if err := s.checkOpen(); err != nil {
993			return err
994		}
995		c, err := s.lookupCampaign(campaignID)
996		if err != nil {
997			return err
998		}
999		if at.IsZero() {
1000			return ErrInvalidTime
1001		}
1002		if at.Before(c.LastTime) {
1003			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
1004		}
1005		if c.Ended {
1006			return nil
1007		}
1008		if at.Before(c.Deadline) {
1009			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
1010			return s.commit(func() error { c.LastTime = at; return nil })
1011		}
1012		return s.commit(func() error {
1013			c.LastTime = at
1014			s.applyTimeout(c, at)
1015			return nil
1016		})
1017	}
1018	
1019	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
1020		if campaignID == "" {
1021			return nil, ErrInvalidCampaignID
1022		}
1023		c, ok := s.campaigns[campaignID]
1024		if !ok {
1025			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
1026		}
1027		return c, nil
1028	}
1029	
1030	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
1031		c, err := s.lookupCampaign(campaignID)
1032		if err != nil {
1033			return nil, nil, err
1034		}
1035		if deviceID == "" {
1036			return nil, nil, ErrInvalidDeviceID
1037		}
1038		i, ok := c.index[deviceID]
1039		if !ok {
1040			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
1041		}
1042		return c, c.Devices[i], nil
1043	}
1044	
1045	// DeviceStatusView 是一台设备在活动中的状态快照。
1046	type DeviceStatusView struct {
1047		DeviceID string
1048		Batch    int
1049		// Status 取 Device* 状态常量，含等待回滚、正在回滚、回滚成功、
1050		// 回滚失败与回滚阶段超时。
1051		Status string
1052		// Phase 是设备当前停留或失败的阶段（download/install/rollback）。
1053		Phase string
1054		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
1055		Reason string
1056		// At 是进入当前状态的时间。
1057		At time.Time
1058		// DownloadID/InstallID/RollbackID 是各阶段操作的稳定标识。
1059		DownloadID string
1060		InstallID  string
1061		RollbackID string
1062		// RollbackTarget 是开启回滚时首次领取下载锁定的回滚目标版本；未锁定为空。
1063		RollbackTarget string
1064		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
1065		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
1066		InstallFailReason string
1067		InstallFailAt     time.Time
1068		// RollbackResult 表示是否已接受回滚结果。
1069		RollbackResult bool
1070		// RollbackSuccess 表示已接受的回滚结果是否成功。
1071		RollbackSuccess bool
1072		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
1073		RollbackReason string
1074		RollbackAt     time.Time
1075	}
1076	
1077	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
1078	type BatchView struct {
1079		Index   int
1080		Devices []DeviceStatusView
1081	}
1082	
1083	// CampaignView 是分批升级活动的只读快照。
1084	type CampaignView struct {
1085		ID            string
1086		Operator      string
1087		TargetVersion string
1088		CreatedAt     time.Time
1089		BatchSize     int
1090		WindowStart   time.Time
1091		WindowEnd     time.Time
1092		Deadline      time.Time
1093		// RollbackOnFailure 表示该活动是否开启安装失败回滚。
1094		RollbackOnFailure bool
1095		// Status 取 Campaign* 状态常量。
1096		Status  string
1097		Ended   bool
1098		EndedAt time.Time
1099		// Devices 按提交次序给出每台设备的状态。
1100		Devices []DeviceStatusView
1101		// Batches 按批次号分组，保留设备提交次序。
1102		Batches []BatchView
1103		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
1104		Results []ResultRecord
