205		}
206		// 较早批量请求仍记录当时的新修订号 1，不能拿设备最新配置比较
207		rec, err := s2.GetBatchRequest("req-1")
208		if err != nil {
209			t.Fatal(err)
210		}
211		if rec.Revisions["dev-1"] != 1 {
212			t.Fatalf("old batch record: %+v", rec.Revisions)
213		}
214		v, _ := s2.Get("dev-1")
