216			t.Fatalf("latest view: %+v", v)
217		}
218	}
219	
220	// 任一设备历史缺失、断开或与当前期望不符都拒绝打开整个存储，
221	// 且原文件内容保持不变。
222	func TestRestoreAuditChainCorruptRefused(t *testing.T) {
223		op := "op"
