287				d.Desired = empty
288				doc.Devices["dev-1"] = d
289			},
290			// 修订号 0、无审计，但期望配置不是空对象
291			"desired not empty at revision zero": func(doc fixStore) {
292				d := doc.Devices["dev-1"]
293				d.Revision = 0
294				d.Desired = a1
295				d.Audit = nil
