324	// 一台设备损坏即拒绝打开整个存储，其他正常设备也不可用。
325	func TestRestoreOneDeviceCorruptRejectsAll(t *testing.T) {
326		doc := twoAuditDoc()
327		doc.Devices["good"] = fixState{
328			Version:  "1.0",
329			Desired:  json.RawMessage(`{}`),
