1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	// rewriteStore 读入已保存的存储文件，用 mutate 改写后写回，返回写回后的字节
13	// （即拒绝打开时必须原样保留的损坏内容）。
14	func rewriteStoreBytes(t *testing.T, dir string, mutate func(map[string]any)) []byte {
15		t.Helper()
16		path := filepath.Join(dir, storeFileName)
17		data, err := os.ReadFile(path)
18		if err != nil {
19			t.Fatal(err)
20		}
21		var doc map[string]any
22		if err := json.Unmarshal(data, &doc); err != nil {
23			t.Fatal(err)
24		}
25		mutate(doc)
26		out, err := json.Marshal(doc)
27		if err != nil {
28			t.Fatal(err)
29		}
30		if err := os.WriteFile(path, out, 0o644); err != nil {
31			t.Fatal(err)
32		}
33		return out
34	}
35	
36	func campaignDoc(doc map[string]any, id string) map[string]any {
37		return doc["campaigns"].(map[string]any)[id].(map[string]any)
38	}
39	
40	func resultDocs(doc map[string]any, id string) []map[string]any {
41		raw := campaignDoc(doc, id)["results"].([]any)
42		out := make([]map[string]any, len(raw))
43		for i, r := range raw {
44			out[i] = r.(map[string]any)
45		}
46		return out
47	}
48	
49	// assertReopenCorrupt 校验被改写的存储拒绝打开，且原文件内容保留不变。
50	func assertReopenCorrupt(t *testing.T, dir string, original []byte) {
51		t.Helper()
52		s, err := Open(dir)
53		if err == nil {
54			s.Close()
55			t.Fatalf("expected ErrCorruptStorage")
56		}
57		if !errors.Is(err, ErrCorruptStorage) {
58			t.Fatalf("error must wrap ErrCorruptStorage: %v", err)
59		}
60		data, rerr := os.ReadFile(filepath.Join(dir, storeFileName))
61		if rerr != nil {
62			t.Fatal(rerr)
63		}
64		// 拒绝打开后重写的内容必须原样保留，不能被空数据或“修复”覆盖。
65		if string(data) != string(original) {
66			// original 是改写后的字节（即磁盘现状），这里只确认 Open 未再改动文件。
67			t.Fatalf("store file modified by rejected open")
68		}
69	}
70	
71	// TestResultHistoryMissingOrExtraRefused 针对“下载成功等待安装、删掉历史仍能打开”
72	// 的问题：缺少、多出、重复或内容矛盾的结果历史都必须拒绝打开整个存储。
73	func TestResultHistoryMissingOrExtraRefused(t *testing.T) {
74		t.Run("history deleted", func(t *testing.T) {
75			s, dir, _ := setupReady(t)
76			defer s.Close()
77			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
78				delete(campaignDoc(doc, "cmp-1"), "results")
79			})
80			assertReopenCorrupt(t, dir, original)
81		})
82		t.Run("history emptied", func(t *testing.T) {
83			_, dir, _ := setupReady(t)
84			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
85				campaignDoc(doc, "cmp-1")["results"] = []any{}
86			})
87			assertReopenCorrupt(t, dir, original)
88		})
89		t.Run("history duplicated", func(t *testing.T) {
90			_, dir, _ := setupReady(t)
91			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
92				rs := resultDocs(doc, "cmp-1")
93				camp := campaignDoc(doc, "cmp-1")
94				camp["results"] = []any{rs[0], rs[0]}
95			})
96			assertReopenCorrupt(t, dir, original)
97		})
98		t.Run("history extra record", func(t *testing.T) {
99			_, dir, _ := setupReady(t)
100			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
101				rs := resultDocs(doc, "cmp-1")
102				extra := map[string]any{
103					"deviceId":    "d1",
104					"operationId": "cmp-1:d1:install",
105					"stage":       "install",
106					"success":     true,
107					"version":     "v2",
108					"at":          "2026-10-02T12:05:00Z",
109				}
110				campaignDoc(doc, "cmp-1")["results"] = []any{rs[0], extra}
111			})
112			assertReopenCorrupt(t, dir, original)
113		})
114		t.Run("success flag contradicted", func(t *testing.T) {
115			_, dir, _ := setupReady(t)
116			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
117				rs := resultDocs(doc, "cmp-1")
118				rs[0]["success"] = false
119				rs[0]["reason"] = "tampered"
120			})
